      {
        "module": "04-ra7883",
        "sections": {
          "bhwe-application-check": {
            "en": {
              "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-application-check.en.2256997127b1.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "2256997127b10697fd89c2ee9b77c12764ab2686f85425ddb1e7287f26d6de5f",
              "sha256": "b0da820707db768147f1211a753ab11fe10d6eca458b814676f637ac7e3f80e5",
              "duration_seconds": 40.542,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Choose a careful explanation",
                  "start_ms": 0,
                  "end_ms": 2360
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Fictional Card A reports eight years of service but only three years under accreditation.",
                  "start_ms": 2660,
                  "end_ms": 9060
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Which explanation is best?",
                  "start_ms": 9360,
                  "end_ms": 11840
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Connect the count to accredited status, check education and the other service conditions, and form a specific CSC question.",
                  "start_ms": 12140,
                  "end_ms": 21460
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Demi should promise neither BHWE nor a job.",
                  "start_ms": 21760,
                  "end_ms": 26680
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "After choosing, read the reasons for all three answers and explain to a partner what needs verification.",
                  "start_ms": 26980,
                  "end_ms": 34340
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Explain conditions and evidence, then verify with CSC.",
                  "start_ms": 34640,
                  "end_ms": 40480
                }
              ]
            },
            "fil": {
              "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-application-check.fil.6a7358ba3748.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "6a7358ba3748df6a80805160d6b67d650774347f824dbb27195844fa6352c69f",
              "sha256": "75762cb30c08452efe7d483b3b6ad3cd051134896da62092fff3198e936a309b",
              "duration_seconds": 44.513,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Piliin ang maingat na paliwanag",
                  "start_ms": 0,
                  "end_ms": 2760
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Sinabi sa kathang-isip na Card A na walong taon na ang serbisyo at tatlong taon pa lamang ang accreditation.",
                  "start_ms": 3060,
                  "end_ms": 10820
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "Aling paliwanag ang pinakamainam?",
                  "start_ms": 11120,
                  "end_ms": 14400
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "Iugnay ang bilang sa accredited status, suriin ang edukasyon at iba pang service conditions, at bumuo ng tiyak na tanong sa CSC.",
                  "start_ms": 14700,
                  "end_ms": 23620
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "Hindi dapat mangako si Demi ng BHWE o trabaho.",
                  "start_ms": 23920,
                  "end_ms": 29160
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "Pagkatapos pumili, basahin ang dahilan para sa lahat ng tatlong sagot at ipaliwanag sa kapareha kung ano ang dapat tiyakin.",
                  "start_ms": 29460,
                  "end_ms": 38860
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Ipaliwanag ang kondisyon at ebidensiya, saka tiyakin sa CSC.",
                  "start_ms": 39160,
                  "end_ms": 44440
                }
              ]
            }
          },
          "bhwe-question": {
            "en": {
              "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-question.en.ccebf4e77f16.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "ccebf4e77f166efaf3cfb5076c736dd3f5a1edfa0e893da32bfe8bd4d3ac028f",
              "sha256": "91535175a0afeb33348c14ded73dee1abdc2932607f9b18dbb5690a8436fed59",
              "duration_seconds": 39.262,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Demi's question",
                  "start_ms": 0,
                  "end_ms": 2320
                },
                {
                  "zone": "body",
                  "index": 0,
                  "text": "Demi hears that accreditation or long BHW service automatically brings BHWE and a government job.",
                  "start_ms": 2620,
                  "end_ms": 12300
                },
                {
                  "zone": "body",
                  "index": 1,
                  "text": "She asks, \u2018Are accreditation, civil service eligibility and appointment the same?\u2019",
                  "start_ms": 12600,
                  "end_ms": 19440
                },
                {
                  "zone": "body",
                  "index": 2,
                  "text": "They are different.",
                  "start_ms": 19740,
                  "end_ms": 21420
                },
                {
                  "zone": "body",
                  "index": 3,
                  "text": "This is a fictional situation; Demi's education and qualifying service are not established.",
                  "start_ms": 21720,
                  "end_ms": 28360
                },
                {
                  "zone": "body",
                  "index": 4,
                  "text": "First understand the conditions and evidence before making a promise.",
                  "start_ms": 28660,
                  "end_ms": 33300
                },
                {
                  "zone": "takeaway",
                  "index": 0,
                  "text": "Accreditation, BHWE approval and appointment are different.",
                  "start_ms": 33600,
                  "end_ms": 39200
                }
              ]
            },
            "fil": {
              "src": "/training/audio/04-ra7883/bhw-eligibility/bhwe-question.fil.c1bc7e73a262.mp3",
              "voice": "gemini:gemini-3.8-flash-tts:Kore",
              "content_hash": "c1bc7e73a262d8602cb13a2180121e781c487481af8f8f8322b7cea318196884",
              "sha256": "362fb276e59091c0d40c74289c4337025b3d44da287a64de088e2a0ead358487",
              "duration_seconds": 39.549,
              "timings": [
                {
                  "zone": "heading",
                  "index": 0,
                  "text": "Tanong ni Demi",
